const { data, isLoading, error } = useQuery({
  queryKey: ["products"],
  queryFn: () =&gt; api.get("/products"),
});

const qc = useQueryClient();
const addProduct = useMutation({
  mutationFn: (p: NewProduct) =&gt; api.post("/products", p),
  onSuccess: () =&gt; qc.invalidateQueries({ queryKey: ["products"] }),
});

export const useCountries = () =&gt;
  useQuery({
    queryKey: ["registry", "countries"],
    queryFn: () =&gt; api.get("/registry/countries"),
    staleTime: Infinity,
  });

type CartState = {
  items: string[];
  add: (sku: string) =&gt; void;
  clear: () =&gt; void;
};

const useCart = create&lt;CartState&gt;((set) =&gt; ({
  items: [],
  add: (sku) =&gt; set((s) =&gt; ({ items: [...s.items, sku] })),
  clear: () =&gt; set({ items: [] }),
}));

const count = useCart((s) =&gt; s.items.length); // re-render solo se count cambia
const add = useCart((s) =&gt; s.add);
// niente &lt;Provider&gt; da montare

const cart = createSlice({
  name: "cart",
  initialState: { items: [] as string[] },
  reducers: {
    add: (s, a: PayloadAction&lt;string&gt;) =&gt; { s.items.push(a.payload); }, // Immer: sembra mutazione
    clear: (s) =&gt; { s.items = []; },
  },
});

const count = useSelector((s: RootState) =&gt; s.cart.items.length);
dispatch(add("sku-1"));

class CartStore {
  items: string[] = [];
  constructor() { makeAutoObservable(this); }
  add(sku: string) { this.items.push(sku); }   // muti direttamente
  get count() { return this.items.length; }     // computed cache-ato
}
export const cartStore = new CartStore();

interface CartState { items: string[]; coupon: string | null }
const cart$ = observable&lt;CartState&gt;({ items: [], coupon: null });

cart$.items.push("sku-1");     // mutazione
cart$.coupon.set("WELCOME");   // set esplicito
const c = cart$.coupon.peek(); // lettura one-shot NON reattiva, tipica nelle callback

function Coupon() {
  const coupon = use$(cart$.coupon);   // reattivo: legato SOLO a questo path
  return &lt;Text&gt;{coupon ?? "nessuno"}&lt;/Text&gt;;
}

syncObservable(
  cart$,
  syncedFetch&lt;CartState&gt;({
    activate: "auto",
    get: "https://api.example.com/cart",
    retry: { infinite: true },
    persist: {
      name: "cart",
      plugin: new ObservablePersistMMKV({ id: "app-state" }),
      retrySync: true,
    },
  }),
);

interface ProductsState { items: Product[]; lastServerSync: string }

abstract class BaseProducts {
  constructor(protected readonly storage: Storage) {}
  protected readonly _state$ = observable&lt;ProductsState&gt;(PRODUCTS_INITIAL);
  get state$(): Observable&lt;ProductsState&gt; { return this._state$; }
}

class Products extends BaseProducts {          // concreta: avvia sync + persist
  constructor(storage: Storage) { super(storage); syncObservable(/* ... */); }
}

class ProductsMock extends BaseProducts {}     // mock no-sync per test e storybook

export function createServices(): AppServices {
  const storage = new Storage();
  const productsState = new Products(storage);
  const cartState = new Cart(storage);
  return { storage, productsState, cartState };
}
